import json, sys

def text_snip(content, n=300):
    if isinstance(content, str):
        return content[:n]
    if isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict):
                continue
            t = c.get('type')
            if t == 'text':
                parts.append(c.get('text','')[:n])
            elif t == 'tool_use':
                inp = c.get('input', {})
                inp_s = json.dumps(inp)[:200]
                parts.append(f"[TOOL_USE {c.get('name')} input={inp_s}]")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    cont = ' '.join(x.get('text','') for x in cont if isinstance(x, dict))
                cont_s = str(cont)[:n]
                err = c.get('is_error')
                parts.append(f"[TOOL_RESULT err={err} {cont_s}]")
        return ' | '.join(parts)
    return str(content)[:n]

def main(path):
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"{i}: PARSE_ERROR {e}")
                continue
            t = obj.get('type')
            ts = obj.get('timestamp', '')
            if t in ('user', 'assistant'):
                msg = obj.get('message', {})
                role = msg.get('role', t)
                content = msg.get('content')
                snip = text_snip(content)
                print(f"{i} [{ts}] {role}: {snip}")
            elif t == 'queue-operation':
                print(f"{i} [{ts}] QUEUE-{obj.get('operation')}: {str(obj.get('content'))[:200]}")
            elif t == 'system':
                pass
            else:
                pass

if __name__ == '__main__':
    main(sys.argv[1])

